namespace System.Windows.Input
{
	/// <summary>Event args for <c>TextInput</c> / <c>PreviewTextInput</c>.</summary>
	public class TextCompositionEventArgs : RoutedEventArgs
	{
		/// <summary>The text generated by the key stroke or IME composition.</summary>
		public string Text { get; }

		/// <param name="routedEvent">The routed event.</param>
		/// <param name="text">The composed text.</param>
		public TextCompositionEventArgs(RoutedEvent routedEvent, string text)
			: base(routedEvent)
		{
			Text = text ?? string.Empty;
		}
	}
}
